actor ImageLoader {
    private let memory = NSCache<NSString, UIImage>()
    private var inFlight: [String: Task<UIImage, Error>] = [:]

    func image(_ url: URL, size: CGSize, scale: CGFloat) async throws -> UIImage {
        let key = "\(url.absoluteString)@\(Int(size.width))x\(Int(size.height))" as NSString
        if let cached = memory.object(forKey: key) { return cached }
        if let task = inFlight[key as String] { return try await task.value }

        let task = Task.detached(priority: .userInitiated) {
            let (data, _) = try await URLSession.shared.data(from: url)   // URLCache = disk cache
            guard let img = downsample(data, to: size, scale: scale) else { throw URLError(.cannotDecodeContentData) }
            return img
        }
        inFlight[key as String] = task
        defer { inFlight[key as String] = nil }
        let image = try await task.value
        memory.setObject(image, forKey: key)
        return image
    }
}
